from decimal import Decimal, getcontext, ROUND_HALF_UP, InvalidOperation

getcontext().prec = 80

Q2 = Decimal("0.01")
LIM_14_2 = Decimal("1000000000000")


class LegacyError(Exception):
    pass


def r2(x):
    return x.quantize(Q2, rounding=ROUND_HALF_UP)


def store_14_2(x):
    # Asignacion a NUMBER(14,2): Oracle redondea a la escala; si excede la precision -> ORA-06502
    v = r2(x)
    if abs(v) >= LIM_14_2:
        raise LegacyError("ORA-06502")
    return v


def fmt2(x):
    v = r2(x)
    if v == 0:
        v = Decimal("0.00")
    return str(v)


def to_dec(s, default="0"):
    if s is None:
        return Decimal(default)
    t = str(s).strip()
    if t == "":
        return Decimal(default)
    try:
        return Decimal(t)
    except InvalidOperation:
        return Decimal(default)


def to_int(s, default=0):
    d = to_dec(s, str(default))
    return int(d)


def to_bool(s):
    if isinstance(s, bool):
        return s
    t = str(s).strip().upper()
    return t in ("TRUE", "1", "Y", "YES", "S", "SI", "T")


def days_from_civil(y, m, d):
    y = y - (1 if m <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def parse_date(s):
    t = str(s).strip()[:10]
    parts = t.split("-")
    return days_from_civil(int(parts[0]), int(parts[1]), int(parts[2]))


def clean_tok(t):
    t = t.strip()
    while len(t) > 0 and t[0] in "\"' ":
        t = t[1:]
    while len(t) > 0 and t[-1] in "\"' ":
        t = t[:-1]
    return t.strip()


def parse_params(p):
    res = {}
    if isinstance(p, dict):
        for k in p:
            v = p[k]
            if v is None:
                res[str(k).strip().upper()] = None
            else:
                vs = str(v).strip()
                if vs == "" or vs.upper() in ("NULL", "NONE"):
                    res[str(k).strip().upper()] = None
                else:
                    try:
                        res[str(k).strip().upper()] = Decimal(vs)
                    except InvalidOperation:
                        res[str(k).strip().upper()] = None
        return res
    if p is None:
        return res
    s = str(p).strip()
    s = s.replace("{", " ").replace("}", " ").replace("\n", ",").replace(";", ",")
    for item in s.split(","):
        if item.strip() == "":
            continue
        sep_pos = -1
        for i in range(len(item)):
            if item[i] in ":=":
                sep_pos = i
                break
        if sep_pos < 0:
            continue
        k = clean_tok(item[:sep_pos]).upper()
        v = clean_tok(item[sep_pos + 1:])
        if k == "":
            continue
        if v == "" or v.upper() in ("NULL", "NONE"):
            res[k] = None
        else:
            try:
                res[k] = Decimal(v)
            except InvalidOperation:
                res[k] = None
    return res


def run(inp: dict) -> dict:
    out = {
        "base_amount": "0.00",
        "deductible_amount": "0.00",
        "covered_amount": "0.00",
        "withholding_amount": "0.00",
        "net_amount": "0.00",
        "liquidation_status": "",
        "reason_code": "",
        "observations": "",
        "claim_new_status": "",
        "error_code": "",
    }

    params = parse_params(inp.get("parameters"))

    def param(code):
        if code not in params:
            raise LegacyError("20010")
        v = params[code]
        if v is None:
            return None
        # LS_PARAMETROS.valor_numerico NUMBER(14,4)
        return v.quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP)

    obs = {"v": None}

    def add_obs(mark):
        if obs["v"] is None or obs["v"] == "":
            obs["v"] = mark
        else:
            obs["v"] = obs["v"] + ";" + mark

    def map_status(st):
        if st == "APROBADA":
            return "LIQUIDADO"
        if st == "RECHAZADA":
            return "RECHAZADO"
        if st == "PENDIENTE_APROBACION":
            return "PENDIENTE_REVISION"
        return ""

    def reject(reason, observations=None):
        out["base_amount"] = "0.00"
        out["deductible_amount"] = "0.00"
        out["covered_amount"] = "0.00"
        out["withholding_amount"] = "0.00"
        out["net_amount"] = "0.00"
        out["liquidation_status"] = "RECHAZADA"
        out["reason_code"] = reason
        out["observations"] = observations if observations else ""
        out["claim_new_status"] = "RECHAZADO"
        return out

    try:
        claim_status = str(inp.get("claim_status", "")).strip()
        if claim_status != "REGISTRADO":
            raise LegacyError("20001")

        claimed = store_14_2(to_dec(inp.get("claimed_amount")))
        occ = parse_date(inp.get("occurrence_date"))
        rep = parse_date(inp.get("report_date"))
        pol_status = str(inp.get("policy_status", "")).strip()
        pol_start = parse_date(inp.get("policy_start_date"))
        pol_end = parse_date(inp.get("policy_end_date"))
        ramo = str(inp.get("line_of_business", "")).strip()
        sum_insured = to_dec(inp.get("sum_insured"))
        ded_type = str(inp.get("deductible_type", "")).strip()
        ded_value = to_dec(inp.get("deductible_value"))
        pending = to_dec(inp.get("pending_premium"))
        category = str(inp.get("customer_category", "")).strip()
        cov_found = to_bool(inp.get("coverage_found", "false"))
        cov_limit = to_dec(inp.get("coverage_limit"))
        cov_pct = to_dec(inp.get("coverage_percentage"))
        waiting = to_int(inp.get("waiting_days"))
        prior_cnt = to_int(inp.get("prior_liquidated_claims_365d"))
        total_indemn = to_dec(inp.get("total_indemnified"))

        # v_factor_inflacion := fn_param_num('FACTOR_INFLACION') (sin uso, pero puede fallar)
        param("FACTOR_INFLACION")

        # 1.a
        if pol_status != "VIGENTE":
            return reject("POLIZA_NO_VIGENTE")

        # 1.b
        if occ < pol_start or occ > pol_end:
            return reject("FUERA_DE_VIGENCIA")

        # 1.c
        dias_denuncia = rep - occ
        if ramo == "VIDA":
            dias_max = param("DIAS_MAX_DENUNCIA_VIDA")
        else:
            dias_max = param("DIAS_MAX_DENUNCIA")
        if dias_max is not None and Decimal(dias_denuncia) > dias_max:
            return reject("DENUNCIA_EXTEMPORANEA")

        # 1.d
        if not cov_found:
            return reject("COBERTURA_NO_CONTRATADA")

        # 1.e
        dias_desde_inicio = occ - pol_start
        if dias_desde_inicio < waiting:
            return reject("EN_PERIODO_CARENCIA")

        # 1.f
        if pending > 0:
            tol = param("TOLERANCIA_MORA_VIP")
            if category == "VIP" and tol is not None and pending <= tol:
                add_obs("TOLERANCIA_MORA_VIP")
            else:
                return reject("PRIMA_EN_MORA", obs["v"])

        # 2.a
        if claimed > cov_limit:
            base = store_14_2(cov_limit)
            add_obs("LIMITE_COBERTURA")
        else:
            base = store_14_2(claimed)

        # 2.b deducible
        if ded_type == "FIJO":
            ded = store_14_2(ded_value)
        else:
            ded_min = param("DEDUCIBLE_MINIMO")
            ded = store_14_2(r2(base * ded_value / Decimal(100)))
            if ded_min is not None and ded < ded_min:
                ded = store_14_2(ded_min)
                add_obs("DEDUCIBLE_MINIMO")
        if category == "VIP" and ded > 0:
            pct_vip = param("PCT_DESCUENTO_DED_VIP")
            if pct_vip is None:
                raise LegacyError("NULL_PARAM_PCT_DESCUENTO_DED_VIP")
            ded = store_14_2(r2(ded * (Decimal(100) - pct_vip) / Decimal(100)))
            add_obs("DESCUENTO_VIP")

        # 2.c
        cubierto = store_14_2(r2((base - ded) * cov_pct / Decimal(100)))
        if cubierto <= 0:
            return reject("BAJO_DEDUCIBLE", obs["v"])

        # 2.d siniestralidad
        max_sin = param("MAX_SINIESTROS_ANUAL")
        if max_sin is not None and Decimal(prior_cnt) >= max_sin:
            pct_pen = param("PCT_PENALIZACION_SINIEST")
            if pct_pen is None:
                raise LegacyError("NULL_PARAM_PCT_PENALIZACION_SINIEST")
            cubierto = store_14_2(r2(cubierto * (Decimal(100) - pct_pen) / Decimal(100)))
            add_obs("PENALIZACION_SINIESTRALIDAD")

        # 2.e suma asegurada remanente
        remanente = sum_insured - total_indemn
        if remanente <= 0:
            return reject("SUMA_ASEGURADA_AGOTADA", obs["v"])
        if cubierto > remanente:
            cubierto = store_14_2(remanente)
            add_obs("TOPE_SUMA_ASEGURADA")

        # 2.f retencion
        retencion = Decimal("0.00")
        if ramo != "VIDA":
            umbral = param("UMBRAL_RETENCION")
            if umbral is not None and cubierto > umbral:
                tasa = param("TASA_RETENCION")
                if tasa is None:
                    raise LegacyError("NULL_PARAM_TASA_RETENCION")
                retencion = store_14_2(r2(cubierto * tasa / Decimal(100)))
                add_obs("RETENCION_APLICADA")
            else:
                retencion = Decimal("0.00")
        neto = store_14_2(cubierto - retencion)

        # 3. estado final
        pct_fraude = param("PCT_ALERTA_FRAUDE")
        umbral_fraude = None
        if pct_fraude is not None:
            umbral_fraude = r2(cov_limit * pct_fraude / Decimal(100))
        dias_fraude = param("DIAS_ALERTA_FRAUDE")
        fraude = False
        if dias_fraude is not None and Decimal(dias_desde_inicio) <= dias_fraude:
            if umbral_fraude is not None and claimed >= umbral_fraude:
                fraude = True
        if fraude:
            estado = "PENDIENTE_APROBACION"
            motivo = "SOSPECHA_FRAUDE"
        else:
            tope = param("TOPE_AUTO_APROBACION")
            if tope is not None and neto > tope:
                estado = "PENDIENTE_APROBACION"
                motivo = "SUPERA_TOPE_AUTOMATICO"
            else:
                estado = "APROBADA"
                motivo = "LIQUIDACION_AUTOMATICA"

        out["base_amount"] = fmt2(base)
        out["deductible_amount"] = fmt2(ded)
        out["covered_amount"] = fmt2(cubierto)
        out["withholding_amount"] = fmt2(retencion)
        out["net_amount"] = fmt2(neto)
        out["liquidation_status"] = estado
        out["reason_code"] = motivo
        out["observations"] = obs["v"] if obs["v"] else ""
        out["claim_new_status"] = map_status(estado)
        return out

    except LegacyError as e:
        code = str(e.args[0]) if len(e.args) > 0 else "ERROR"
        out["base_amount"] = "0.00"
        out["deductible_amount"] = "0.00"
        out["covered_amount"] = "0.00"
        out["withholding_amount"] = "0.00"
        out["net_amount"] = "0.00"
        out["liquidation_status"] = ""
        out["reason_code"] = ""
        out["observations"] = ""
        out["claim_new_status"] = ""
        out["error_code"] = code
        return out
